const SCENARIOS = [
            { id: 'scenario1_baseline', name: 'Scenario 1: Baseline', color: '#ef4444', chkId: 'chk-s1' },
            { id: 'scenario2_congestion', name: 'Scenario 2: Congestion', color: '#f59e0b', chkId: 'chk-s2' },
            { id: 'scenario3_countermeasures', name: 'Scenario 3: Countermeasures', color: '#10b981', chkId: 'chk-s3' },
            { id: 'scenario4_both_factors', name: 'Scenario 4: Two-Factor', color: '#0ea5e9', chkId: 'chk-s4' },
            { id: 'scenario5_delayed_patching', name: 'Scenario 5: Delayed Patch', color: '#a855f7', chkId: 'chk-s5' }
        ];

        let activeTab = 'tab-comparison';
        let inspectedTime = 300;

        function switchTab(tabId) {
            document.querySelectorAll('.tab-btn').forEach(b => b.classList.remove('active'));
            document.querySelectorAll('.tab-content').forEach(c => c.classList.remove('active'));
            
            event.target.classList.add('active');
            document.getElementById(tabId).classList.add('active');
            activeTab = tabId;
            setTimeout(renderCharts, 50);
        }

        function selectScenario(scenId) {
            document.querySelectorAll('.metric-card').forEach(c => c.classList.remove('active-card'));
            const cardMap = {
                'scenario1_baseline': '.card-s1',
                'scenario2_congestion': '.card-s2',
                'scenario3_countermeasures': '.card-s3',
                'scenario4_both_factors': '.card-s4',
                'scenario5_delayed_patching': '.card-s5'
            };
            const target = document.querySelector(cardMap[scenId]);
            if (target) target.classList.add('active-card');
        }

        function updateTimeScrubber(val) {
            inspectedTime = parseInt(val, 10);
            document.getElementById('sliderReadout').innerText = 't = ' + inspectedTime;
            renderCharts();
        }

        // =====================================================================
        // CANVAS CHART ENGINE (Crisp High-DPI Rendering)
        // =====================================================================
        function setupCanvas(canvas) {
            const dpr = window.devicePixelRatio || 1;
            const rect = canvas.getBoundingClientRect();
            canvas.width = rect.width * dpr;
            canvas.height = rect.height * dpr;
            const ctx = canvas.getContext('2d');
            ctx.scale(dpr, dpr);
            return { ctx, width: rect.width, height: rect.height };
        }

        function drawMultiLineChart(canvasId, metricKey, yMaxVal, yLabel) {
            const canvas = document.getElementById(canvasId);
            if (!canvas) return;
            const { ctx, width, height } = setupCanvas(canvas);

            const padding = { top: 25, right: 30, bottom: 40, left: 70 };
            const plotW = width - padding.left - padding.right;
            const plotH = height - padding.top - padding.bottom;

            ctx.clearRect(0, 0, width, height);

            // Draw Grid & Axes
            ctx.strokeStyle = '#334155';
            ctx.lineWidth = 1;
            ctx.beginPath();

            // Y-Grid & Labels
            const ySteps = 5;
            ctx.fillStyle = '#64748b';
            ctx.font = '11px monospace';
            ctx.textAlign = 'right';
            ctx.textBaseline = 'middle';

            for (let i = 0; i <= ySteps; i++) {
                const yVal = (yMaxVal / ySteps) * i;
                const yPos = padding.top + plotH - (plotH / ySteps) * i;
                
                ctx.moveTo(padding.left, yPos);
                ctx.lineTo(padding.left + plotW, yPos);
                
                let label = yVal >= 1000 ? (yVal / 1000).toFixed(0) + 'k' : yVal.toFixed(0);
                ctx.fillText(label, padding.left - 10, yPos);
            }

            // X-Grid & Labels
            const xSteps = 8;
            ctx.textAlign = 'center';
            ctx.textBaseline = 'top';

            for (let i = 0; i <= xSteps; i++) {
                const tVal = (2000 / xSteps) * i;
                const xPos = padding.left + (plotW / xSteps) * i;
                
                ctx.moveTo(xPos, padding.top);
                ctx.lineTo(xPos, padding.top + plotH);
                
                ctx.fillText('t=' + tVal, xPos, padding.top + plotH + 8);
            }
            ctx.stroke();

            // Draw Y-Axis Title
            ctx.save();
            ctx.translate(16, padding.top + plotH / 2);
            ctx.rotate(-Math.PI / 2);
            ctx.textAlign = 'center';
            ctx.fillStyle = '#94a3b8';
            ctx.font = '11px sans-serif';
            ctx.fillText(yLabel, 0, 0);
            ctx.restore();

            // Plot curves
            SCENARIOS.forEach(scen => {
                const chk = document.getElementById(scen.chkId);
                if (chk && !chk.checked) return;

                const series = RAW_DATA[scen.id];
                if (!series || series.length === 0) return;

                ctx.strokeStyle = scen.color;
                ctx.lineWidth = 2.5;
                ctx.lineJoin = 'round';
                ctx.beginPath();

                series.forEach((pt, idx) => {
                    const x = padding.left + (pt.t / 2000) * plotW;
                    const val = pt[metricKey] || 0;
                    const y = padding.top + plotH - (val / yMaxVal) * plotH;
                    if (idx === 0) ctx.moveTo(x, y);
                    else ctx.lineTo(x, y);
                });
                ctx.stroke();
            });

            // Draw Inspected Time Vertical Indicator
            if (inspectedTime >= 0 && inspectedTime <= 2000) {
                const curX = padding.left + (inspectedTime / 2000) * plotW;
                ctx.save();
                ctx.strokeStyle = '#38bdf8';
                ctx.lineWidth = 1.5;
                ctx.setLineDash([4, 4]);
                ctx.beginPath();
                ctx.moveTo(curX, padding.top);
                ctx.lineTo(curX, padding.top + plotH);
                ctx.stroke();
                ctx.restore();

                // Circle at points
                SCENARIOS.forEach(scen => {
                    const chk = document.getElementById(scen.chkId);
                    if (chk && !chk.checked) return;

                    const series = RAW_DATA[scen.id];
                    if (!series) return;

                    // Find closest point
                    let closest = series[0];
                    let minDiff = 999999;
                    series.forEach(pt => {
                        const diff = Math.abs(pt.t - inspectedTime);
                        if (diff < minDiff) { minDiff = diff; closest = pt; }
                    });

                    const val = closest[metricKey] || 0;
                    const ptY = padding.top + plotH - (val / yMaxVal) * plotH;

                    ctx.fillStyle = scen.color;
                    ctx.beginPath();
                    ctx.arc(curX, ptY, 4, 0, Math.PI * 2);
                    ctx.fill();
                    ctx.strokeStyle = '#ffffff';
                    ctx.lineWidth = 1.5;
                    ctx.stroke();
                });
            }
        }

        function renderCharts() {
            if (activeTab === 'tab-comparison') {
                drawMultiLineChart('canvasComparison', 'j', 380000, 'Cumulative Infected Hosts J(t)');
            } else if (activeTab === 'tab-active') {
                drawMultiLineChart('canvasActive', 'i', 380000, 'Active Infectious Hosts I(t)');
            } else if (activeTab === 'tab-delay') {
                drawMultiLineChart('canvasDelay', 'j', 380000, 'Cumulative Infected Hosts J(t)');
            }
        }

        window.addEventListener('resize', renderCharts);
        window.addEventListener('DOMContentLoaded', () => {
            renderCharts();
        });